# region: fold
def fold(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: sift
def sift(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: intake
def intake(xs, offset=1):
    return [v + offset for v in xs]

# region: shape
def shape(xs):
    return [v * v for v in xs[1:]]

# region: gather
def gather(xs, cut=5):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: render
def render(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return render(gather(shape(intake(sift(fold(raw))))))

